// "Who has access" list in the share dialog. One line per allow entry, sorted.
export function listAccess(node) {
  const seen = new Set();
  const result = [];
  let cur = node;
  while (cur) {
    for (const e of cur.acl) {
      if (e.effect !== 'allow') continue;
      const key = `${e.principal}\0${e.role}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (cur === node) {
        result.push(`${e.principal}: ${e.role}`);
      } else {
        result.push(`${e.principal}: ${e.role} (inherited from ${cur.path()})`);
      }
    }
    if (!cur.inherit || !cur.parent) break;
    cur = cur.parent;
  }
  return result.sort();
}

