// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._appliedIds = new Set();
    this._bufferedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Stale seq: already applied
    if (event.seq <= this.lastSeq) {
      return [];
    }
    // Idempotency by id
    if (this._appliedIds.has(event.id)) {
      return [];
    }
    if (this._bufferedIds.has(event.id)) {
      return [];
    }
    // Duplicate seq already buffered (different id) -> keep first, ignore new
    if (this._buffer.has(event.seq)) {
      return [];
    }

    const applied = [];

    if (event.seq === this.lastSeq + 1) {
      this._applyAndTrack(event);
      applied.push(event);

      // Drain contiguous buffered events - delete only after successful apply
      while (this._buffer.has(this.lastSeq + 1)) {
        const nextSeq = this.lastSeq + 1;
        const next = this._buffer.get(nextSeq);
        this._applyAndTrack(next);
        this._buffer.delete(nextSeq);
        this._bufferedIds.delete(next.id);
        applied.push(next);
      }
    } else {
      // Future seq -> buffer
      this._buffer.set(event.seq, event);
      this._bufferedIds.add(event.id);
    }

    return applied;
  }

  _applyAndTrack(event) {
    this.apply(event);
    this.lastSeq = event.seq;
    this._appliedIds.add(event.id);
  }
}
